using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Drawing.Imaging;using System.Reflection;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {static class LauncherNativeServicesTests {
 static JavaScriptSerializer j=new JavaScriptSerializer(); static void Check(bool v,string label){if(!v)throw new Exception("FAIL: "+label);Console.WriteLine("PASS: "+label);}
 static object Call(string cls,string method,params object[] args){var t=typeof(Program).Assembly.GetType("PZ3D."+cls);Check(t!=null,"native service exists: "+cls);try{return t.GetMethod(method).Invoke(null,args);}catch(TargetInvocationException ex){throw ex.InnerException;}}
 static Dictionary<string,object> D(object o){return j.Deserialize<Dictionary<string,object>>(j.Serialize(o));}
 static void Refuses(Action a,string label){bool denied=false;try{a();}catch{denied=true;}Check(denied,label);}
 public static int Main(){try{Run();return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
 public static void Run(){string root=Path.Combine(LauncherTestPaths.Root,"native-services-"+Guid.NewGuid().ToString("N")),game=Path.Combine(root,"game"),user=Path.Combine(root,"user"),data=Path.Combine(root,"data");Directory.CreateDirectory(game);Directory.CreateDirectory(user);var e=new Engine(game,user,data,true);
  string save=Path.Combine(user,"Saves","Sandbox","测试 存档");Directory.CreateDirectory(save);using(var b=new Bitmap(4,4)){b.SetPixel(0,0,Color.Orange);b.Save(Path.Combine(save,"thumb.png"),ImageFormat.Png);}var thumb=D(Call("LauncherPictures","Save",e,"Sandbox/测试 存档"));Check(Convert.ToString(thumb["dataUrl"]).StartsWith("data:image/png;base64,"),"save original PNG is exposed as bounded data URL");Refuses(()=>Call("LauncherPictures","Save",e,"Sandbox/../outside"),"save thumbnail traversal refused");File.WriteAllText(Path.Combine(save,"thumb.png"),"not a PNG");Check(D(Call("LauncherPictures","Save",e,"Sandbox/测试 存档"))["dataUrl"]==null,"invalid thumbnail is not exposed");
  var target=new ServerLaunchTarget{Host="example.test",Port=16261,Username="alice"};string serverSave=Path.Combine(user,"Saves","Multiplayer","example.test_16261_6384e2b2184bcbf58eccf10ca7a6563c");Directory.CreateDirectory(serverSave);using(var b=new Bitmap(3,3))b.Save(Path.Combine(serverSave,"thumb.png"),ImageFormat.Png);Check(D(Call("LauncherPictures","Server",e,target))["dataUrl"]!=null,"server role uses exact game MD5 folder");target.Username="bob";Check(D(Call("LauncherPictures","Server",e,target))["dataUrl"]==null,"another role screenshot is never selected");
  string journalData=Path.Combine(root,"journal");object journal=Activator.CreateInstance(typeof(Program).Assembly.GetType("PZ3D.LauncherJournal"),new object[]{journalData});var type=journal.GetType();string id=(string)type.GetMethod("Begin").Invoke(journal,new object[]{"maintenance","清除多人缓存"});type.GetMethod("Update").Invoke(journal,new object[]{25,"正在删除 1 / 4；password=secret-value token=abc-ticket"});type.GetMethod("Finish").Invoke(journal,new object[]{"failed","未完成 password=secret-value"});object second=Activator.CreateInstance(type,new object[]{journalData});var snapshot=D(type.GetMethod("Snapshot").Invoke(second,null));string json=j.Serialize(snapshot);Check(json.Contains("failed")&&json.Contains("25")&&!json.Contains("secret-value")&&!json.Contains("abc-ticket"),"task journal persists measured failure progress and redacts credentials");Check(!json.Contains("\"progress\":100"),"failed task is not fabricated completed100");string next=(string)type.GetMethod("Begin").Invoke(second,new object[]{"maintenance","中断测试"});string recordFile=Path.Combine(journalData,"diagnostics","tasks.json");File.WriteAllText(recordFile,System.Text.RegularExpressions.Regex.Replace(File.ReadAllText(recordFile),@"\""ownerPid\"":\d+","\"ownerPid\":999999"));object third=Activator.CreateInstance(type,new object[]{journalData});Check(j.Serialize(type.GetMethod("Snapshot").Invoke(third,null)).Contains("interrupted"),"startup marks abandoned local task interrupted");
  var playData=Path.Combine(root,"play");Call("PlaytimeTracker","Sample",playData,"fixture-session",new DateTime(2026,1,1,15,59,55,DateTimeKind.Utc),true);Call("PlaytimeTracker","Sample",playData,"fixture-session",new DateTime(2026,1,1,16,0,5,DateTimeKind.Utc),true);var time=D(Call("PlaytimeTracker","SnapshotAt",playData,new DateTime(2026,1,1,16,0,5,DateTimeKind.Utc)));Check(Convert.ToInt32(time["totalSeconds"])==10&&Convert.ToInt32(time["sessionSeconds"])==10,"playtime counts process sampling not launcher lifetime");Call("PlaytimeTracker","Sample",playData,"fixture-session",new DateTime(2026,1,1,18,0,5,DateTimeKind.Utc),true);time=D(Call("PlaytimeTracker","SnapshotAt",playData,new DateTime(2026,1,1,18,0,5,DateTimeKind.Utc)));Check(Convert.ToInt32(time["totalSeconds"])==10,"heartbeat loss cannot fabricate hours offline");Call("PlaytimeTracker","Sample",playData,"fixture-session",new DateTime(2026,1,1,18,0,10,DateTimeKind.Utc),false);Check(!Convert.ToBoolean(D(Call("PlaytimeTracker","SnapshotAt",playData,new DateTime(2026,1,1,18,0,10,DateTimeKind.Utc)))["running"]),"stopped session is no longer running");Console.WriteLine("NATIVE SERVICES PASSED at "+root);
 }
}}
